function hexToRgb(h){h=h.replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)];}
function rgb2hsl(r,g,b){r/=255;g/=255;b/=255;var mx=Math.max(r,g,b),mn=Math.min(r,g,b);var l=(mx+mn)/2,h,s;if(mx===mn){h=s=0}else{var d=mx-mn;s=l>0.5?d/(2-mx-mn):d/(mx+mn);switch(mx){case r:h=(g-b)/d+(g<b?6:0);break;case g:h=(b-r)/d+2;break;default:h=(r-g)/d+4}h/=6}return[h*360,s,l];}
var accents={accent05:'#eff1f9',accent10:'#e0e4f2',accent15:'#d0d6ec',accent20:'#c0c9e6',accent25:'#b1bbdf',accent30:'#a1aed9',accent35:'#91a0d3',accent40:'#8292cc',accent45:'#7285c6',accent50:'#6578ba',accent55:'#5c6da9',accent60:'#536298',accent65:'#4a5787',accent70:'#404c76',accent75:'#374165',accent80:'#2e3654',accent85:'#252b43',accent90:'#1b2032',accent95:'#121521'};
for(var k in accents){var c=hexToRgb(accents[k]);var hsl=rgb2hsl(c[0],c[1],c[2]);
 var lOld=Math.min(1,1.3-hsl[2]);
